## Overview
Create the foundational storage models and fileStorage persistence keys that all other issues depend on.

## File to Create
`Sources/SharedModels/ToolIOStorage.swift`

## Implementation

### 1. Storage Models
```swift
import Foundation

public struct ToolIOStorage: Codable, Equatable {
    public var input: String
    public var output: String

    public init(input: String = "", output: String = "") {
        self.input = input
        self.output = output
    }
}

// For RegexMatches which has two outputs
public struct ToolIOStorageDoubleOutput: Codable, Equatable {
    public var input: String
    public var output: String
    public var outputSecond: String

    public init(input: String = "", output: String = "", outputSecond: String = "") {
        self.input = input
        self.output = output
        self.outputSecond = outputSecond
    }
}
```

### 2. URL Extensions
```swift
extension URL {
    static var toolStorageDirectory: URL {
        .documentsDirectory.appending(component: "ToolStorage")
    }

    static func toolStorage(_ tool: String) -> URL {
        toolStorageDirectory.appending(component: "\(tool).json")
    }
}
```

### 3. FileStorage Keys
```swift
import ComposableArchitecture

extension PersistenceReaderKey where Self == FileStorageKey<ToolIOStorage> {
    static var textCaseConverterIO: Self { .fileStorage(.toolStorage("textCaseConverter")) }
    static var prefixSuffixIO: Self { .fileStorage(.toolStorage("prefixSuffix")) }
    static var htmlToSwiftIO: Self { .fileStorage(.toolStorage("htmlToSwift")) }
    static var swiftPrettyIO: Self { .fileStorage(.toolStorage("swiftPretty")) }
    static var jsonPrettyIO: Self { .fileStorage(.toolStorage("jsonPretty")) }
}

extension PersistenceReaderKey where Self == FileStorageKey<ToolIOStorageDoubleOutput> {
    static var regexMatchesIO: Self { .fileStorage(.toolStorage("regexMatches")) }
}
```

## Acceptance Criteria
- [ ] ToolIOStorage struct is Codable and Equatable
- [ ] ToolIOStorageDoubleOutput struct is Codable and Equatable
- [ ] All 6 tool fileStorage keys are defined
- [ ] Code compiles with no errors

## Notes
- This is a **blocking dependency** - all other issues depend on this
- No other code changes needed, just create this new file

